def cm_grade(correct,total):
    if type(correct) is not int or type(total) is not int or total<1 or not 0<=correct<=total:return 'white'
    if total<=10:return 'gold' if correct==total else 'silver' if correct==total-1 else 'bronze' if correct==total-2 else 'white'
    return 'gold' if correct*10>=total*9 else 'silver' if correct*10>=total*8 else 'bronze' if correct*10>=total*7 else 'white'
