@st.cache_resource
def get_supabase():
    from supabase import create_client
    return create_client(
        st.secrets["SUPABASE_URL"],
        st.secrets["SUPABASE_SERVICE_ROLE_KEY"],
    )


@st.cache_data(ttl=3000, show_spinner=False)
def get_bgm_urls():
    # One Storage request for all tracks, after the first interactive screen.
    bucket = get_supabase().storage.from_(BUCKET_NAME)
    rows = bucket.create_signed_urls(BGM_FILES, SIGNED_URL_EXPIRES_IN)
    if isinstance(rows,dict):rows=rows.get('data',[])
    urls={}
    for row in rows:
        if not isinstance(row,dict):continue
        path=row.get('path');url=row.get('signedURL') or row.get('signedUrl') or row.get('signed_url')
        if isinstance(url,str) and url.startswith('/object/sign/'):
            url=str(st.secrets['SUPABASE_URL']).rstrip('/')+'/storage/v1'+url
        elif isinstance(url,str) and url.startswith('/storage/v1/object/sign/'):
            url=str(st.secrets['SUPABASE_URL']).rstrip('/')+url
        if path in BGM_FILES and isinstance(url,str) and url.startswith('https://') and not row.get('error'):
            urls[path]=url
    if len(urls)!=len(BGM_FILES):raise RuntimeError('bgm_urls_incomplete')
    return urls


def prepare_deferred_bgm():
    if _startup_time.time()<st.session_state.get('startup_bgm_next_load_at',0):return
    st.session_state['startup_bgm_next_load_at']=_startup_time.time()+30
    started=_startup_time.perf_counter()
    try:st.session_state['startup_bgm_urls']=get_bgm_urls()
    except Exception:st.session_state['startup_bgm_status']='unavailable'
    else:
        st.session_state['startup_bgm_status']='ready'
        st.session_state['startup_bgm_next_load_at']=_startup_time.time()+3000
    st.session_state.setdefault('startup_timings',{})['bgm_urls_ms']=round((_startup_time.perf_counter()-started)*1000,2)


